if (n == b.size) {
    return true;
}

if (n < b.size) {
    b.size = n;
    return true;
}

// Try to expand in-place
size_t current_offset = p - data;
size_t aligned_start = (current_offset + alignment - 1) & ~(alignment - 1);
size_t next_block_start = (current_offset + b.size);

// Check if there is enough space remaining in the buffer for the new size
if (next_block_start + (n - b.size) <= max_size) {
    b.size = n;
    return true;
}

// Allocate new block
char* new_p = nullptr;
if (allocate(new_p, data, max_size, alignment, b, n)) {
    std::memcpy(new_p, p, b.size);
    // Note: In a stack allocator, we typically don't "deallocate" 
    // individual blocks unless it's the top one, but the logic 
    // for reallocate usually implies moving the pointer.
    p = new_p;
    b.size = n;
    return true;
}

return false;
// END_CODE

